-- PREPARED ONLY: V-01..V-08 connected private Web/Desktop quality workspace.
-- Not applied. No native/Android writer, QM original, care record, visit, plan or employee record is changed.
-- Required runtime gates: PostgreSQL/PostgREST/RLS/grants, two-session CAS/deadlock/rollback,
-- SDK argument names, native/legacy writer compatibility, browser/layout and qualified care/privacy/legal acceptance.
begin;
create schema if not exists quality_workspace_private;
revoke all on schema quality_workspace_private from public,anon,authenticated;
create table if not exists quality_workspace_private.roots(tenant_id uuid primary key,head_id uuid,updated_at timestamptz not null default clock_timestamp());
create table if not exists quality_workspace_private.events(id uuid primary key,tenant_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),kind text not null,command jsonb not null,unique(tenant_id,sequence),unique(tenant_id,request_id));
alter table quality_workspace_private.roots enable row level security;alter table quality_workspace_private.events enable row level security;
revoke all on all tables in schema quality_workspace_private from public,anon,authenticated;
create or replace function quality_workspace_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception using errcode='P0P01',message='Qualitätsverlauf bleibt unveränderlich.';end$$;
drop trigger if exists quality_workspace_roots_delete on quality_workspace_private.roots;create trigger quality_workspace_roots_delete before delete on quality_workspace_private.roots for each row execute function quality_workspace_private.immutable();
drop trigger if exists quality_workspace_events_immutable on quality_workspace_private.events;create trigger quality_workspace_events_immutable before update or delete on quality_workspace_private.events for each row execute function quality_workspace_private.immutable();

create or replace function quality_workspace_private.profile_has(t uuid,a uuid,keys text[])returns boolean language sql stable set search_path='' as $$
select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and not exists(select 1 from unnest(keys)k where not case when exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key)then exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key and z.permission_key=k)else exists(select 1 from public.role_permissions z where z.role_id=r.id and z.permission_key=k)end))$$;
create or replace function quality_workspace_private.kind_right(k text)returns text language sql immutable set search_path='' as $$select case when k in('document_version','document_acknowledgement')then'qm.edit_document'when k='document_release'then'qm.approve_document'when k in('inspection_mapping','complaint_intake','complaint_investigation','complaint_response','incident_report','causal_analysis','visit_schedule','visit_occurrence','visit_finding')then'qm.create_audit'when k='complaint_closure'then'qm.close_audit'when k in('corrective_action','effectiveness_review','event_analysis','care_plan_adjustment','repeat_check','visit_follow_up','correction')then'qm.create_measure'when k in('incident_closure','acceptance_scope','scenario_result','acceptance_decision')then'qm.close_measure'end$$;
create or replace function quality_workspace_private.extra_rights(k text)returns text[] language sql immutable set search_path='' as $$select case when k='care_plan_adjustment'then array['pflege.plans.manage']when k in('visit_schedule','visit_occurrence','visit_finding','visit_follow_up')then array['pflege.visits.manage']else array[]::text[]end$$;
create or replace function quality_workspace_private.actor(t uuid,a uuid,k text default null)returns text language plpgsql security definer set search_path='' as $$
declare sid uuid;n text;permission text;required text[]:=array['qm.view','qm.view_versions','office.clients.view','office.clients.view_sensitive','pflege.visits.view','pflege.plans.view','pflege.audit.view','pflege.documentation.view'];begin
 if auth.uid()is null or auth.uid()is distinct from a or public.resolve_current_profile_id()is distinct from a or public.current_tenant_id()is distinct from t or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())then raise exception using errcode='42501',message='Aktuelles eigenes Konto fehlt.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;perform 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid()and(s.not_after is null or s.not_after>clock_timestamp())for share;if not found then raise exception using errcode='42501',message='Aktuelle native Sitzung fehlt.';end if;
 permission:=quality_workspace_private.kind_right(k);if k is not null and permission is null then raise exception using errcode='22023',message='Qualitätsvorgang ist unbekannt.';end if;if permission is not null then required:=required||permission||quality_workspace_private.extra_rights(k);lock table public.roles,public.role_permissions,public.role_permission_sets in share mode;end if;
 select coalesce(nullif(btrim(p.display_name),''),'Name nicht bestätigt')into n from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid())for share of p,r;
 if n is null or not quality_workspace_private.profile_has(t,a,required)then raise exception using errcode='42501',message='Aktuelle QM-, Pflegeakten- oder Bearbeitungsrechte fehlen.';end if;foreach permission in array required loop if public.has_permission(permission)is not true then raise exception using errcode='42501',message='Nativer Rechtezugang fehlt.';end if;end loop;return n;
end$$;
create or replace function quality_workspace_private.event_json(e quality_workspace_private.events)returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)$$;
create or replace function quality_workspace_private.history(t uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e quality_workspace_private.events%rowtype;head uuid;prev uuid;n bigint:=0;rows jsonb:='[]';begin select r.head_id into head from quality_workspace_private.roots r where r.tenant_id=t;for e in select*from quality_workspace_private.events z where z.tenant_id=t order by z.sequence loop if e.sequence<>n+1 or e.previous_id is distinct from prev or e.command->>'eventId'is distinct from e.id::text or e.command->>'tenantId'is distinct from t::text or e.command->>'actorId'is distinct from e.actor_id::text or(e.command->>'expectedHeadId')is distinct from prev::text then raise exception using errcode='23514',message='Qualitätsverlauf ist widersprüchlich.';end if;rows:=rows||jsonb_build_array(quality_workspace_private.event_json(e));prev:=e.id;n:=n+1;end loop;if head is distinct from prev then raise exception using errcode='23514',message='Qualitätsverlaufskopf ist unvollständig.';end if;return jsonb_build_object('version','2026-10-16.1','tenantId',t,'count',n,'headId',head,'events',rows);end$$;

create or replace function quality_workspace_private.sources(t uuid)returns jsonb language sql security definer set search_path='' as $$
with s as(
 select'qm_document'::text kind,x.id,to_jsonb(x)snapshot from public.qm_documents x where x.tenant_id=t
 union all select'qm_document_version',x.id,to_jsonb(x)from public.qm_document_versions x where x.tenant_id=t
 union all select'qm_document_approval',x.id,to_jsonb(x)from public.qm_document_versions x where x.tenant_id=t and x.status='approved'
 union all select'qm_read_confirmation',x.id,to_jsonb(x)from public.qm_read_confirmations x where x.tenant_id=t
 union all select'qm_audit',x.id,to_jsonb(x)from public.qm_quality_inspection_evidence_sets x where x.tenant_id=t
 union all select'qm_inspection_requirement',x.id,to_jsonb(x)from public.qm_quality_inspection_requirements x where x.tenant_id=t
 union all select'record',x.id,to_jsonb(x)from public.qm_quality_inspection_evidence_refs x where x.tenant_id=t
 union all select'qm_complaint',x.id,to_jsonb(x)from public.qm_complaints x where x.tenant_id=t
 union all select'qm_complaint_event',x.id,to_jsonb(x)from public.qm_complaint_events x where x.tenant_id=t
 union all select'qm_safety_incident',x.id,to_jsonb(x)from public.qm_safety_incidents x where x.tenant_id=t
 union all select'qm_safety_event',x.id,to_jsonb(x)from public.qm_safety_incident_events x where x.tenant_id=t
 union all select'qm_fall_analysis',x.id,to_jsonb(x)from public.qm_fall_event_analyses x where x.tenant_id=t
 union all select'qm_fall_event',x.id,to_jsonb(x)from public.qm_fall_event_analysis_events x where x.tenant_id=t
 union all select'care_record',x.id,to_jsonb(x)from public.care_records x where x.tenant_id=t
 union all select'care_plan_version',x.id,to_jsonb(x)from public.care_plans x where x.tenant_id=t
 union all select'client',x.id,to_jsonb(x)from public.clients x where x.tenant_id=t
 union all select'care_visit',x.id,to_jsonb(x)from public.care_quality_visits x where x.tenant_id=t
 union all select'care_visit_record',x.id,to_jsonb(x)from public.care_quality_visits x where x.tenant_id=t and x.conducted_at is not null
 union all select'care_visit_finding',x.id,to_jsonb(x)from public.care_quality_visits x where x.tenant_id=t and(nullif(btrim(x.findings),'')is not null or nullif(btrim(x.deviations),'')is not null)
 union all select'qm_measure_follow_up',x.id,to_jsonb(x)from public.qm_quality_measure_follow_ups x where x.tenant_id=t
 union all select'qm_measure_event',x.id,to_jsonb(x)from public.qm_quality_measure_follow_up_events x where x.tenant_id=t
 union all select'acceptance_scope',x.id,to_jsonb(x)from public.qm_ambulatory_professional_acceptances x where x.tenant_id=t
 union all select'professional_acceptance',x.id,to_jsonb(x)from public.qm_ambulatory_professional_acceptances x where x.tenant_id=t
 union all select'acceptance_scenario',x.id,to_jsonb(x)from public.qm_ambulatory_professional_acceptance_events x where x.tenant_id=t and x.event_kind='scenario_performed'
 union all select'employee_qualification',x.id,to_jsonb(x)from public.qm_ambulatory_professional_acceptance_events x where x.tenant_id=t and nullif(btrim(x.reviewer_qualification),'')is not null
)select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;
create or replace function quality_workspace_private.source_rules(k text)returns jsonb language sql immutable set search_path='' as $$select case k
when'document_version'then'{"document":["qm_document"],"version":["qm_document_version"]}'when'document_release'then'{"version":["qm_document_version"],"approval":["qm_document_approval"]}'when'document_acknowledgement'then'{"version":["qm_document_version"],"acknowledgement":["qm_read_confirmation"]}'when'inspection_mapping'then'{"audit":["qm_audit"],"requirement":["qm_inspection_requirement"],"record":["record","qm_document_version"]}'
when'complaint_intake'then'{"complaint":["qm_complaint"]}'when'complaint_investigation'then'{"complaint":["qm_complaint"],"investigation":["qm_complaint_event"]}'when'complaint_response'then'{"complaint":["qm_complaint"],"response":["qm_complaint_event"]}'when'complaint_closure'then'{"complaint":["qm_complaint"],"investigation":["qm_complaint_event"],"response":["qm_complaint_event"]}'
when'incident_report'then'{"incident":["qm_safety_incident"]}'when'causal_analysis'then'{"incident":["qm_safety_incident"],"analysis":["qm_safety_event","qm_fall_analysis"]}'when'corrective_action'then'{"deviation":["qm_safety_incident","qm_complaint","qm_inspection_requirement"],"measure":["qm_measure_follow_up"]}'when'effectiveness_review'then'{"measure":["qm_measure_follow_up"],"review":["qm_measure_event"]}'when'incident_closure'then'{"incident":["qm_safety_incident"],"cause":["qm_safety_event","qm_fall_event"],"action":["qm_measure_event","qm_safety_event"],"review":["qm_measure_event","qm_safety_event"]}'
when'event_analysis'then'{"incident":["qm_safety_incident"],"careRecord":["care_record"],"analysis":["qm_fall_analysis"]}'when'care_plan_adjustment'then'{"analysis":["qm_fall_analysis"],"carePlan":["care_plan_version"],"adjustment":["qm_fall_event"]}'when'repeat_check'then'{"analysis":["qm_fall_analysis"],"adjustment":["qm_fall_event"],"careRecord":["care_record"]}'
when'visit_schedule'then'{"client":["client"],"visit":["care_visit"]}'when'visit_occurrence'then'{"visit":["care_visit"],"record":["care_visit_record"]}'when'visit_finding'then'{"visit":["care_visit_record"],"finding":["care_visit_finding"]}'when'visit_follow_up'then'{"finding":["care_visit_finding"],"measure":["qm_measure_follow_up"]}'
when'acceptance_scope'then'{"scope":["acceptance_scope"],"acceptance":["professional_acceptance"]}'when'scenario_result'then'{"acceptance":["professional_acceptance"],"scenario":["acceptance_scenario"],"qualification":["employee_qualification"]}'when'acceptance_decision'then'{"acceptance":["professional_acceptance"],"scenario":["acceptance_scenario"],"qualification":["employee_qualification"]}'when'correction'then'{}'end::jsonb$$;
create or replace function quality_workspace_private.field_rules(k text)returns jsonb language sql immutable set search_path='' as $$select case k
when'document_version'then'{"versionLabel":"text","validFrom":"date","contentSha256":"sha256"}'when'document_release'then'{"decision":["released","rejected"],"validFrom":"date","decisionReason":"text"}'when'document_acknowledgement'then'{"readerId":"uuid","acknowledgedAt":"instant","scopeSha256":"sha256"}'when'inspection_mapping'then'{"requirementCode":"text","recordLocator":"text","gapState":["evidenced","open_gap"],"gapNote":"text"}'
when'complaint_intake'then'{"scope":["client","facility"],"concern":"text","recipientId":"uuid","dueAt":"instant"}'when'complaint_investigation'then'{"finding":"text","recordLocator":"text","resultSha256":"sha256"}'when'complaint_response'then'{"recipient":"text","channel":"text","responseSummary":"text","responseSha256":"sha256"}'when'complaint_closure'then'{"decision":["closed","reopened"],"resultSummary":"text","resultSha256":"sha256"}'
when'incident_report'then'{"classification":["error","near_miss"],"category":"text","observedAt":"instant","impactSummary":"text"}'when'causal_analysis'then'{"causeSummary":"text","certainty":["confirmed","probable","possible","unknown"],"uncertaintyNote":"text"}'when'corrective_action'then'{"action":"text","responsibleId":"uuid","dueAt":"instant"}'when'effectiveness_review'then'{"observedFrom":"instant","observedUntil":"instant","outcome":["effective","partially_effective","not_effective","insufficient_evidence"],"result":"text","resultSha256":"sha256"}'when'incident_closure'then'{"outcome":["risk_controlled","follow_up_required","closed_without_harm_inference"],"closureSha256":"sha256"}'
when'event_analysis'then'{"eventType":["fall","other"],"factorSummary":"text","causeCertainty":["confirmed","probable","possible","unknown"]}'when'care_plan_adjustment'then'{"responsibleId":"uuid","effectiveAt":"instant","plannedReviewAt":"instant","adjustmentSummary":"text"}'when'repeat_check'then'{"observedFrom":"instant","observedUntil":"instant","recurrence":["observed","not_observed","unclear"],"outcome":["effective","partially_effective","not_effective","insufficient_observation"],"resultSha256":"sha256"}'
when'visit_schedule'then'{"scheduledAt":"instant","reviewerId":"uuid","focus":"text"}'when'visit_occurrence'then'{"occurredAt":"instant","reviewerId":"uuid","recordSha256":"sha256"}'when'visit_finding'then'{"findingSummary":"text","deviationState":["none","open","critical"],"recordLocator":"text"}'when'visit_follow_up'then'{"action":"text","responsibleId":"uuid","dueAt":"instant"}'
when'acceptance_scope'then'{"scopeLabel":"text","scopeSha256":"sha256","requiredScenarioIds":"text"}'when'scenario_result'then'{"reviewerId":"uuid","scenarioResult":["passed","failed","blocked"],"resultSummary":"text","resultSha256":"sha256"}'when'acceptance_decision'then'{"decision":["accepted","accepted_with_restrictions","not_accepted"],"decisionReason":"text","restriction":"text","decisionSha256":"sha256"}'when'correction'then'{"targetId":"uuid","reason":"text","evidenceSha256":"sha256"}'end::jsonb$$;
create or replace function quality_workspace_private.validate_command(cmd jsonb,src jsonb)returns void language plpgsql set search_path='' as $$
declare k text:=cmd->>'kind';p jsonb:=cmd->'payload';sources jsonb:=quality_workspace_private.source_rules(k);fields jsonb:=quality_workspace_private.field_rules(k);actual text[];expected text[];entry record;v jsonb;begin
 select array_agg(x order by x)into actual from jsonb_object_keys(cmd)x;if jsonb_typeof(cmd)is distinct from'object'or actual is distinct from array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version']::text[]or cmd->>'version'<>'2026-10-16.1'or cmd->>'requestId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'tenantId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'actorId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or(cmd->'expectedHeadId'<>'null'::jsonb and cmd->>'expectedHeadId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')or cmd->>'occurredAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'or nullif(btrim(cmd->>'note'),'')is null or length(cmd->>'note')>4000 or jsonb_typeof(p)is distinct from'object'or sources is null or fields is null then raise exception using errcode='22023',message='Qualitätsanfrage ist unvollständig.';end if;
 select array_agg(key order by key)into expected from(select jsonb_object_keys(sources)key union all select jsonb_object_keys(fields))q;select array_agg(x order by x)into actual from jsonb_object_keys(p)x;if actual is distinct from expected then raise exception using errcode='22023',message='Vorgangsfelder sind unvollständig oder enthalten Fremdfelder.';end if;
 for entry in select key,value from jsonb_each(sources)loop v:=p->entry.key;if jsonb_typeof(v)is distinct from'object'or(select array_agg(x order by x)from jsonb_object_keys(v)x)is distinct from array['id','kind','snapshot']::text[]or not exists(select 1 from jsonb_array_elements(entry.value)x where x#>>'{}'=v->>'kind')or v->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or jsonb_typeof(v->'snapshot')is distinct from'object'or v#>>'{snapshot,id}'is distinct from v->>'id'or not exists(select 1 from jsonb_array_elements(src)x where x=v)then raise exception using errcode='40001',message='Originalquelle ist falsch, geändert oder nicht mehr zugänglich.';end if;end loop;
 for entry in select key,value from jsonb_each(fields)loop if nullif(btrim(p->>entry.key),'')is null then raise exception using errcode='22023',message='Pflichtangabe fehlt.';end if;if jsonb_typeof(entry.value)='array'and not exists(select 1 from jsonb_array_elements(entry.value)x where x#>>'{}'=p->>entry.key)then raise exception using errcode='22023',message='Auswahlwert ist unbekannt.';elsif entry.value='"uuid"'and(p->>entry.key)!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'then raise exception using errcode='22P02',message='UUID ist ungültig.';elsif entry.value='"sha256"'and(p->>entry.key)!~'^[0-9a-f]{64}$'then raise exception using errcode='22023',message='Fingerabdruck ist ungültig.';elsif entry.value='"date"'and((p->>entry.key)!~'^\d{4}-\d{2}-\d{2}$'or to_char(to_date(p->>entry.key,'YYYY-MM-DD'),'YYYY-MM-DD')<>p->>entry.key)then raise exception using errcode='22007',message='Datum ist ungültig.';elsif entry.value='"instant"'and(p->>entry.key)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then raise exception using errcode='22007',message='Zeitpunkt ist ungültig.';end if;end loop;
 if k in('effectiveness_review','repeat_check')and((p->>'observedFrom')::timestamptz>(p->>'observedUntil')::timestamptz or(p->>'observedUntil')::timestamptz>(cmd->>'occurredAt')::timestamptz)then raise exception using errcode='22007',message='Beobachtungszeitraum ist widersprüchlich.';end if;
end$$;

create or replace function quality_workspace_private.read_context(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare n text;src jsonb;begin n:=quality_workspace_private.actor(t,a,null);src:=quality_workspace_private.sources(t);return jsonb_build_object('version','2026-10-16.1','tenantId',t,'actorId',a,'loadedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'history',quality_workspace_private.history(t));end$$;
create or replace function quality_workspace_private.commit_event(cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare t uuid:=(cmd->>'tenantId')::uuid;a uuid:=(cmd->>'actorId')::uuid;rid uuid:=(cmd->>'requestId')::uuid;eid uuid:=(cmd->>'eventId')::uuid;n text;root quality_workspace_private.roots%rowtype;e quality_workspace_private.events%rowtype;src jsonb;begin
 n:=quality_workspace_private.actor(t,a,cmd->>'kind');perform pg_advisory_xact_lock(hashtextextended('quality-workspace:'||t::text,0));lock table public.qm_documents,public.qm_document_versions,public.qm_read_confirmations,public.qm_quality_inspection_evidence_sets,public.qm_quality_inspection_requirements,public.qm_quality_inspection_evidence_refs,public.qm_complaints,public.qm_complaint_events,public.qm_safety_incidents,public.qm_safety_incident_events,public.qm_fall_event_analyses,public.qm_fall_event_analysis_events,public.care_records,public.care_plans,public.clients,public.care_quality_visits,public.qm_quality_measure_follow_ups,public.qm_quality_measure_follow_up_events,public.qm_ambulatory_professional_acceptances,public.qm_ambulatory_professional_acceptance_events in share mode;
 insert into quality_workspace_private.roots(tenant_id)values(t)on conflict do nothing;select*into root from quality_workspace_private.roots r where r.tenant_id=t for update;select*into e from quality_workspace_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is not null then if e.command is distinct from cmd then raise exception using errcode='23505',message='Anfragekennung gehört zu anderem Inhalt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',quality_workspace_private.event_json(e));end if;
 src:=quality_workspace_private.sources(t);perform quality_workspace_private.validate_command(cmd,src);if(cmd->>'expectedHeadId')is distinct from root.head_id::text then raise exception using errcode='40001',message='Qualitätsverlauf wurde geändert.';end if;
 if cmd->>'kind'='correction'and not exists(select 1 from quality_workspace_private.events x where x.tenant_id=t and x.id=(cmd#>>'{payload,targetId}')::uuid and x.kind<>'correction'and not exists(select 1 from quality_workspace_private.events z where z.tenant_id=t and z.kind='correction'and z.command#>>'{payload,targetId}'=x.id::text))then raise exception using errcode='23514',message='Nur ein vorhandenes unberichtigtes Original kann berichtigt werden.';end if;
 insert into quality_workspace_private.events(id,tenant_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,coalesce((select max(sequence)+1 from quality_workspace_private.events where tenant_id=t),1),root.head_id,rid,a,n,(cmd->>'occurredAt')::timestamptz,cmd->>'kind',cmd)returning*into e;update quality_workspace_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',cmd,'event',quality_workspace_private.event_json(e));
end$$;
create or replace function quality_workspace_private.confirm_event(t uuid,a uuid,rid uuid,cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e quality_workspace_private.events%rowtype;begin perform quality_workspace_private.actor(t,a,null);select*into e from quality_workspace_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is null or e.command is distinct from cmd or e.actor_id<>a then raise exception using errcode='P0P01',message='Passende native Quittung fehlt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',quality_workspace_private.event_json(e));end$$;
create or replace function public.web_quality_workspace_context(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select quality_workspace_private.read_context(p_tenant_id,p_actor_id)$$;
create or replace function public.web_commit_quality_workspace_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select quality_workspace_private.commit_event(p_command)$$;
create or replace function public.web_confirm_quality_workspace_event(p_tenant_id uuid,p_actor_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select quality_workspace_private.confirm_event(p_tenant_id,p_actor_id,p_request_id,p_command)$$;
revoke all on function public.web_quality_workspace_context(uuid,uuid),public.web_commit_quality_workspace_event(jsonb),public.web_confirm_quality_workspace_event(uuid,uuid,uuid,jsonb)from public,anon;
grant usage on schema quality_workspace_private to authenticated;
grant execute on function quality_workspace_private.read_context(uuid,uuid),quality_workspace_private.commit_event(jsonb),quality_workspace_private.confirm_event(uuid,uuid,uuid,jsonb)to authenticated;
grant execute on function public.web_quality_workspace_context(uuid,uuid),public.web_commit_quality_workspace_event(jsonb),public.web_confirm_quality_workspace_event(uuid,uuid,uuid,jsonb)to authenticated;
commit;
